:root {
  --bg: #faf6ef;
  --surface: #ffffff;
  --ink: #2b2118;
  --muted: #7a6a5a;
  --line: #e8dfd2;
  --crust: #a8551f;
  --crust-dark: #8a4416;
  --crust-soft: #f6e8db;
  --ok: #2f7a4b;
  --ok-soft: #e3f2e8;
  --warn: #9a6a00;
  --warn-soft: #fbf0d4;
  --err: #b3261e;
  --err-soft: #fbe5e3;
  --radius: 14px;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 16px/1.5 var(--sans);
}
h1, h2, h3 { font-family: var(--serif); font-weight: 600; line-height: 1.2; margin: 0; }
a { color: var(--crust-dark); }
button, input, select, textarea { font: inherit; color: inherit; }
:focus-visible { outline: 3px solid color-mix(in srgb, var(--crust) 55%, transparent); outline-offset: 2px; }

.wrap { max-width: 1120px; margin: 0 auto; padding: 0 20px; }

/* ---------- header ---------- */
.site-header { border-bottom: 1px solid var(--line); background: var(--surface); }
.site-header .wrap { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding-top: 14px; padding-bottom: 14px; }
.brand { font-family: var(--serif); font-size: 1.4rem; font-weight: 600; text-decoration: none; color: var(--ink); }
.header-meta { color: var(--muted); font-size: .9rem; text-align: right; }

.hero { padding: 40px 0 24px; }
.hero h1 { font-size: clamp(1.9rem, 4vw, 2.6rem); }
.hero p { color: var(--muted); margin: 8px 0 0; max-width: 46ch; }
.notice {
  display: inline-flex; gap: 8px; align-items: center; margin-top: 16px;
  background: var(--crust-soft); color: var(--crust-dark);
  padding: 8px 14px; border-radius: 999px; font-size: .92rem; font-weight: 500;
}

/* ---------- layout ---------- */
.layout { display: grid; grid-template-columns: 1fr 360px; gap: 32px; align-items: start; padding-bottom: 64px; }
@media (max-width: 900px) { .layout { grid-template-columns: 1fr; } }

.category { margin-top: 28px; }
.category:first-child { margin-top: 0; }
.category h2 { font-size: 1.25rem; margin-bottom: 12px; }

.menu-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 14px; }
.item {
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 16px; display: flex; flex-direction: column; gap: 6px;
  transition: border-color .15s, box-shadow .15s;
}
.item.in-cart { border-color: var(--crust); box-shadow: 0 0 0 1px var(--crust); }
.item.unavailable { opacity: .55; }
.item img { width: 100%; aspect-ratio: 4/3; object-fit: cover; border-radius: 10px; margin-bottom: 6px; }
.item-head { display: flex; justify-content: space-between; gap: 10px; align-items: baseline; }
.item h3 { font-size: 1.08rem; }
.price { font-weight: 600; white-space: nowrap; }
.item p { margin: 0; color: var(--muted); font-size: .92rem; flex: 1; }
.item-foot { display: flex; justify-content: space-between; align-items: center; margin-top: 8px; min-height: 40px; }
.stock { font-size: .82rem; color: var(--muted); }
.stock.low { color: var(--warn); font-weight: 500; }
.stock.out { color: var(--err); font-weight: 500; }

.stepper { display: inline-flex; align-items: center; border: 1px solid var(--line); border-radius: 999px; overflow: hidden; }
.stepper button {
  width: 38px; height: 38px; border: 0; background: transparent; cursor: pointer; font-size: 1.15rem;
}
.stepper button:hover:not(:disabled) { background: var(--crust-soft); }
.stepper button:disabled { opacity: .35; cursor: not-allowed; }
.stepper output { min-width: 26px; text-align: center; font-weight: 600; }

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  border: 0; border-radius: 999px; cursor: pointer; font-weight: 600;
  background: var(--crust); color: #fff; padding: 10px 18px;
}
.btn:hover:not(:disabled) { background: var(--crust-dark); }
.btn:disabled { opacity: .5; cursor: not-allowed; }
.btn.secondary { background: var(--surface); color: var(--ink); border: 1px solid var(--line); }
.btn.secondary:hover:not(:disabled) { background: var(--crust-soft); }
.btn.block { width: 100%; padding: 14px; font-size: 1.02rem; }
.btn.small { padding: 6px 12px; font-size: .88rem; }

/* ---------- order panel ---------- */
.panel {
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 20px; position: sticky; top: 20px;
}
@media (max-width: 900px) { .panel { position: static; } }
.panel h2 { font-size: 1.3rem; margin-bottom: 14px; }
.panel section + section { margin-top: 18px; padding-top: 18px; border-top: 1px solid var(--line); }
.label { display: block; font-size: .85rem; font-weight: 600; margin-bottom: 6px; }
.hint { font-size: .82rem; color: var(--muted); font-weight: 400; }

.days { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 4px; scrollbar-width: thin; }
.day {
  flex: 0 0 auto; border: 1px solid var(--line); background: var(--surface); border-radius: 10px;
  padding: 6px 10px; cursor: pointer; text-align: center; min-width: 58px;
}
.day small { display: block; color: var(--muted); font-size: .72rem; text-transform: uppercase; letter-spacing: .04em; }
.day strong { font-size: 1rem; }
.day[aria-pressed="true"] { background: var(--ink); border-color: var(--ink); color: #fff; }
.day[aria-pressed="true"] small { color: #d9cfc3; }

select, input[type=text], input[type=tel], input[type=email], input[type=password], input[type=date], textarea {
  width: 100%; border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; background: var(--surface);
}
textarea { resize: vertical; min-height: 64px; }
.field + .field { margin-top: 12px; }

.cart-lines { list-style: none; margin: 0; padding: 0; }
.cart-lines li { display: flex; justify-content: space-between; gap: 10px; padding: 4px 0; font-size: .95rem; }
.cart-lines .qty { color: var(--muted); margin-right: 6px; }
.empty { color: var(--muted); font-size: .95rem; margin: 0; }
.total { display: flex; justify-content: space-between; font-weight: 700; font-size: 1.1rem; margin-top: 10px; padding-top: 10px; border-top: 1px dashed var(--line); }
.pay-note { font-size: .82rem; color: var(--muted); margin: 10px 0 0; text-align: center; }

.errors { background: var(--err-soft); color: var(--err); border-radius: 10px; padding: 10px 14px; font-size: .92rem; margin: 0 0 12px; }
.errors ul { margin: 0; padding-left: 18px; }

/* mobile sticky bar */
.mobile-bar { display: none; }
@media (max-width: 900px) {
  .mobile-bar {
    display: flex; position: fixed; left: 0; right: 0; bottom: 0; z-index: 10;
    padding: 12px 16px calc(12px + env(safe-area-inset-bottom)); background: var(--surface);
    border-top: 1px solid var(--line); box-shadow: 0 -4px 16px rgba(43, 33, 24, .08);
  }
  .mobile-bar[hidden] { display: none; }
  body.has-bar { padding-bottom: 80px; }
}

.site-footer { border-top: 1px solid var(--line); color: var(--muted); font-size: .88rem; padding: 24px 0 40px; }
.site-footer .wrap { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 16px; }
.hours-list { display: grid; grid-template-columns: auto auto; gap: 2px 16px; margin: 0; }
.hours-list dt { text-transform: capitalize; }
.hours-list dd { margin: 0; }

/* ---------- confirmation ---------- */
.confirm { max-width: 560px; margin: 40px auto 64px; }
.confirm .card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 28px; }
.code { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 1.6rem; letter-spacing: .12em; font-weight: 700; color: var(--crust-dark); }
.check { width: 48px; height: 48px; border-radius: 50%; background: var(--ok-soft); color: var(--ok); display: grid; place-items: center; font-size: 1.5rem; margin-bottom: 14px; }
.kv { display: grid; grid-template-columns: 110px 1fr; gap: 6px 12px; margin: 18px 0; }
.kv dt { color: var(--muted); }
.kv dd { margin: 0; font-weight: 500; }

.badge { display: inline-block; padding: 2px 10px; border-radius: 999px; font-size: .78rem; font-weight: 600; text-transform: capitalize; }
.badge.placed { background: var(--crust-soft); color: var(--crust-dark); }
.badge.ready { background: var(--ok-soft); color: var(--ok); }
.badge.collected { background: #ece8e3; color: var(--muted); }
.badge.cancelled { background: var(--err-soft); color: var(--err); }

.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

